#!/usr/bin/env python3
"""Customise the Android project generated by `tauri android init`.

The generated project (app/src-tauri/gen/android) is not committed, so CI re-creates it on every
build and runs this script afterwards. It is idempotent and fails loudly if the template changes.

Currently: microphone permission (manifest + runtime request).
"""
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parent / "src-tauri" / "gen" / "android" / "app" / "src" / "main"
MANIFEST = ROOT / "AndroidManifest.xml"
ACTIVITY = ROOT / "java" / "net" / "noert" / "mumblefunk" / "MainActivity.kt"

PERMISSIONS = [
    "android.permission.RECORD_AUDIO",
    "android.permission.MODIFY_AUDIO_SETTINGS",
]

ACTIVITY_KT = """package net.noert.mumblefunk

import android.Manifest
import android.content.pm.PackageManager
import android.os.Bundle
import androidx.activity.enableEdgeToEdge
import androidx.activity.result.contract.ActivityResultContracts
import androidx.core.content.ContextCompat

class MainActivity : TauriActivity() {
  // Result is not needed here: the app reports a clear audio error if the permission is missing.
  private val micPermission = registerForActivityResult(ActivityResultContracts.RequestPermission()) { }

  override fun onCreate(savedInstanceState: Bundle?) {
    enableEdgeToEdge()
    super.onCreate(savedInstanceState)
    if (ContextCompat.checkSelfPermission(this, Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) {
      micPermission.launch(Manifest.permission.RECORD_AUDIO)
    }
  }
}
"""


def fail(msg: str) -> None:
    print(f"android-patch: {msg}", file=sys.stderr)
    sys.exit(1)


def patch_manifest() -> None:
    text = MANIFEST.read_text(encoding="utf-8")
    anchor = '<uses-permission android:name="android.permission.INTERNET" />'
    if anchor not in text:
        fail("INTERNET permission anchor not found in AndroidManifest.xml (template changed?)")
    for perm in PERMISSIONS:
        line = f'<uses-permission android:name="{perm}" />'
        if line not in text:
            text = text.replace(anchor, f"{anchor}\n    {line}", 1)
    MANIFEST.write_text(text, encoding="utf-8")


def patch_activity() -> None:
    if not ACTIVITY.exists():
        fail(f"{ACTIVITY} not found")
    ACTIVITY.write_text(ACTIVITY_KT, encoding="utf-8")


for p in (MANIFEST, ACTIVITY):
    if not p.exists():
        fail(f"{p} not found - run `cargo tauri android init` first")
patch_manifest()
patch_activity()
print("android-patch: applied")
